                        item { Text(if (replacementTarget != null) "CHOOSE A MATCH Â· REPLACE FLAGGED CARD" else "SEARCH RESULTS Â· tap + to add to library", color = CounterGold, fontSize = 9.sp, fontWeight = FontWeight.Bold) }
                        items(results.size) { index ->
                            val result = results[index]
                            Row(Modifier.fillMaxWidth().clip(RoundedCornerShape(8.dp)).background(PanelLight).padding(horizontal = 10.dp, vertical = 6.dp), verticalAlignment = Alignment.CenterVertically) {
